from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")


def _nvl_number(value: Any) -> Decimal:
    """Apply legacy numeric NVL/empty-string coercion."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    return row.get("DEL_FLG", "") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the documented invoiced-order cancellation workflow."""
    if order.get("STAT_CD") != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    updated_order = dict(order)

    if new_status == "I":
        return updated_order, [], []

    if new_status == "X":
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """Recompute live order-line extensions and the discounted order total."""
    updated_order = dict(order)
    updated_lines = [dict(line) for line in lines]

    # Invoiced and cancelled totals are deliberately frozen.  Deleted headers are
    # likewise excluded from the legacy nightly recompute.
    if updated_order.get("STAT_CD") in ("I", "X") or _is_deleted(updated_order):
        return updated_order, updated_lines, []

    total = Decimal("0")

    for line in updated_lines:
        if _is_deleted(line):
            continue

        extension = _round_cents(
            _nvl_number(line.get("QTY")) * _nvl_number(line.get("UNIT_PRC"))
        )
        line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _round_cents(
        total * (Decimal("100") - _nvl_number(updated_order.get("DISC_PCT")))
        / Decimal("100")
    )

    stored_total = _nvl_number(updated_order.get("TOT_AMT"))
    if stored_total != discounted_total:
        updated_order["TOT_AMT"] = float(discounted_total)
        return updated_order, updated_lines, ["ORD_RETOTAL"]

    return updated_order, updated_lines, []
